const upsertConversationLink = `-- name: UpsertConversationLink :exec
INSERT INTO agents.conversation_links (conversation_id, customer_id, contact_ids, seen_at)
VALUES ($1, $2::integer, $3::integer[], $4::timestamptz)
ON CONFLICT (conversation_id) DO UPDATE SET
    customer_id = EXCLUDED.customer_id,
    contact_ids = EXCLUDED.contact_ids,
    seen_at = EXCLUDED.seen_at
`

type UpsertConversationLinkParams struct {
	ConversationID uuid.UUID
	CustomerID     *int32
	ContactIds     []int32
	Now            time.Time
}

func (q *Queries) UpsertConversationLink(ctx context.Context, arg UpsertConversationLinkParams) error {
	_, err := q.db.Exec(ctx, upsertConversationLink,
		arg.ConversationID,
		arg.CustomerID,
		arg.ContactIds,
		arg.Now,
	)
	return err
}

